/**
 * An API route never exports `revalidate`.
 *
 * On a live-data route it turns the GET into a build-time static page whose
 * background regeneration can silently never land: one route served its
 * deploy-time snapshot for ten hours. CDN caching belongs in an explicit
 * `Cache-Control: public, s-maxage=N, stale-while-revalidate=M` header on a
 * dynamic route. A route that serves build-time constants uses
 * `dynamic = 'force-static'` and is regenerated by a deploy.
 */
import { describe, it, expect } from '@jest/globals';
import { readdirSync, readFileSync, statSync } from 'fs';
import { join, relative } from 'path';

const API_DIR = join(process.cwd(), 'app', 'api');

function routeFiles(dir: string): string[] {
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (statSync(full).isDirectory()) out.push(...routeFiles(full));
    else if (name === 'route.ts') out.push(full);
  }
  return out;
}

describe('API routes do not export revalidate', () => {
  const files = routeFiles(API_DIR);

  it('finds the API routes', () => {
    expect(files.length).toBeGreaterThan(50);
  });

  it('no route.ts exports revalidate', () => {
    const offenders = files
      .filter((f) => /^export\s+const\s+revalidate\b/m.test(readFileSync(f, 'utf8')))
      .map((f) => relative(process.cwd(), f).replace(/\\/g, '/'));
    expect(offenders).toEqual([]);
  });
});
